pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny gap = pure dead space
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        } else {
            score -= 10.0; // large residual still reusable
        }
    } else {
        score -= 40.0; // perfect fit, strongly reward
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space
    // or the next item fits better in a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + progress * 10.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 20.0; // fresh bin reserves room for the lookahead item
        }
        if post_residual > 0 && post_residual <= 20 {
            score += 15.0; // current placement would create dead space
        }
    }

    // Lookahead: penalize if the leftover cannot host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Mild tie-break toward bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 20 {
        // Non-linear penalty peaking just below the usable threshold.
        score += (20.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit: strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still accommodate a mid/large item later.
    if post_residual >= 20 {
        score -= 8.0;
        if post_residual >= 50 {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize trapping the residual.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0));
    score += pressure * 3.0;

    // Mean-residual coupling: prefer bins tighter than the mean (good packing).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: only attractive when item is large and
    // existing residuals would leave big dead space.
    if bin_residual == bin_capacity {
        // Baseline neutral-ish score; discourage early in the stream.
        score = post_residual as f64 + 25.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // Encourage new bin for large items with poor existing fits.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // If many open bins with small residuals, opening fresh is fine.
        if mean_residual < 25.0 && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    // A gap that cannot plausibly hold even the smallest future item is dead space.
    let dead_threshold = 10.0; // below this, nothing (sizes >= 1) is guaranteed reusable
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize mid-range gaps (too small for typical items, too big to ignore)
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Reward tight fits
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: mild penalty proportional to gap size
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer using existing ones
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: bins with residual far below mean are scarce-resource;
    // placing into them wastes their smallness. Prefer bins near/above mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
        // if no open bin fits, opening is nearly forced
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

