pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in stream, be more conservative (prefer tight fits);
    // later, allow new bins more freely since waste matters less per-item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let urgency = (1.0 - progress).powf(1.5);

    // Penalize large post-residual more strongly as stream progresses (dead space compounds).
    score += (post_residual as f64) * 0.15 * (1.0 - progress);

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual <= 10 {
        score -= 40.0 * (11.0 - post_residual as f64);
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 * urgency;
    }

    // Lookahead coupling: if next item could fit into this bin's post-residual,
    // reward placing here (keeps future options open).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (post_residual as f64 - next_item_size as f64 + 1.0).sqrt();
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Penalize leaving a residual that's too small for the next item (dead space).
        score += 15.0 * urgency;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty
    // so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 70.0 * urgency;
        // But if the item is large relative to capacity and mean residual is small,
        // opening fresh is attractive.
        let density = item_size as f64 / bin_capacity as f64;
        score -= 90.0 * density * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        // Late in the stream, new bins are cheaper.
        score -= 50.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > bin_capacity as f64 * 0.3 {
        score -= 20.0;
    }

    // Mild penalty for wasting a very large bin residual on a small item.
    if item_size < 20 && bin_residual > 80 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills the remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits into post-residual: strong reward scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 40.0 + 60.0 * tightness;
    }
    // Next item cannot fit: penalize proportionally to wasted dead space potential.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable residuals (dead space) more than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare post-residual relative to mean residual of open bins:
    // placing into a bin with above-average residual keeps balance.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score -= 0.3 * (pr - mean_residual);
    } else {
        score += 0.3 * (mean_residual - pr);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    // Early in stream, be slightly more willing to open fresh bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score += 20.0 * progress - 10.0 * (1.0 - progress);
    }

    score
}

