pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial shaping.
    let mut score = norm_pr;

    // Non-linear coupling: tight fits are rewarded more as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 0.6 * progress * tightness * tightness;

    // Penalize residual that is quadratic in waste, weighted by stream maturity.
    score += 0.4 * (1.0 - progress) * norm_pr * norm_pr;

    // Smooth interaction of post_residual with mean residual state.
    let mr = mean_residual / cap;
    score += 0.3 * norm_pr * mr;

    // Lookahead: reward leaving room for the next item smoothly.
    let next = next_item_size as f64 / cap;
    if next > 0.0 {
        let gap = (next - norm_pr).abs();
        score += 0.25 * (1.0 - progress) * gap * gap;
        score -= 0.2 * (norm_pr - next).max(0.0) * (norm_pr - next).max(0.0);
    }

    // Last-chance bonus: strongly favor the only fitting bin, scaled smoothly.
    if fitting_bins_count == 1 {
        score -= 0.5 * tightness;
    }

    // Mild penalty on opening new bins when many bins are open (smooth in count).
    let open_f = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 0.35 + 0.05 * open_f.sqrt() + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins grouped into capacity-fraction classes.
    let quarter = bin_capacity / 4;               // 25 units
    let eighth = bin_capacity / 8;                // ~12 units
    let post = post_residual as u32;

    // Dead-space penalty: residual too small to be useful for typical items.
    if post > 0 && post < eighth {
        score += 40.0 * (eighth - post) as f64 / eighth as f64;
    }

    // Harmonic reward for residuals that are multiples of quarter classes
    // (residual in {0, 25, 50, 75} are "perfect" fill states).
    let harmonic = post % quarter;
    if harmonic == 0 {
        score -= 30.0;
    } else if harmonic <= eighth {
        score -= 10.0;
    } else if harmonic >= quarter - eighth {
        score += 8.0; // near-full but awkward class
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score += slack * 0.35; // penalize leaving mismatched slack
        } else {
            // next item won't fit here; slight bonus for tight current fit
            score -= 5.0 * (1.0 - post as f64 / cap);
        }
    }

    // Prefer tight fits: reward small post_residual relative to capacity.
    score -= 25.0 * (1.0 - post as f64 / cap);

    // Progress-based open-bin control: late in the stream, discourage
    // proliferating bins when mean residual is already large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        score += 35.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).sqrt();
        }
        if progress > 0.5 && mean_residual > cap * 0.3 {
            score += 25.0 * (mean_residual / cap);
        }
    } else {
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny gap: pure dead space
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize large leftover space only mildly — big gaps can still fit future items.
    if post_residual > 60 {
        score += 5.0;
    }

    // Open-bins pressure: prefer tighter packing when many bins are open.
    let pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    score += pressure * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the next item: penalize
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
        if fitting_bins_count > 0 {
            score += 20.0; // discourage abandoning open bins that fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover slack after hypothetical pair.
            let pair_left = post_residual - next_item_size;
            score -= 300.0 - 0.5 * pair_left as f64;
        } else {
            // next item cannot follow here: dead-space risk grows with tightness.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Compare against mean residual: prefer bins that are relatively full already.
    score += 0.4 * (mean_residual - post_residual as f64).abs().signum() * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits mildly.
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current bin leaves unusable sliver.
    if bin_residual == bin_capacity {
        let sliver = post_residual < 10 && post_residual > 0;
        if sliver {
            score -= 60.0; // prefer fresh bin over creating tiny dead space
        } else {
            score += 250.0; // discourage opening new bins unnecessarily
        }
    }

    // Early in stream: keep bins balanced slightly; late: pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less dead space relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large post-residuals that are too small to fit typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement;
    // otherwise penalize slightly for chaining risk.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < next_item_size / 2 {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 50.0;
        }
    }

    // New-bin candidate handling: prefer opening a new bin only when existing bins
    // are mostly full or the fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early: fewer open bins -> cheaper to open; Late: consolidate.
        score += 20.0 * progress + 0.5 * open_bins_count as f64;
        // If existing bins are quite full, opening a new bin is fine.
        if mean_residual < 20.0 {
            score -= 25.0;
        }
        // Large items relative to mean residual: new bin attractive.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is close to the item (best-fit flavor).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * gap;
        // Prefer bins below mean residual (consolidating emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild exploration term coupling time horizon and bin count.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score += (horizon * std::f64::consts::PI).sin() * 2.0
        + 0.01 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial base: reward tight fits (low post_residual)
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let dead_space_penalty = pr_norm * pr_norm * (1.0 + 3.0 * progress) * cap;
    score += dead_space_penalty;

    // Cubic interaction: near-full bins get extra late-stage reward
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * tightness * (10.0 + 40.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Prefer bins tighter than the mean residual (smooth coupling)
    score += 0.5 * (pr - mean_residual) * (0.5 + progress);

    // Mild penalty for spreading across many open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bins whose post_residual falls into "harmonic" classes
    // (divisible cleanly by common small item sizes) leave reusable space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Harmonic class of post_residual: how many standard classes it belongs to
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += 8.0;
            }
        }
        score -= harmonic_bonus;

        // Dead-space penalty: residual in awkward zone (1..9 or 51..59 style gaps)
        if pr < 10 {
            score += 15.0; // unusable for min-size items
        } else if pr > 50 {
            score -= 5.0; // still broadly reusable
        }

        // Integer-division threshold: residual divided into capacity quarters
        let quarter = bin_capacity / 4;
        if pr >= 3 * quarter {
            score -= 6.0;
        } else if pr >= 2 * quarter {
            score -= 2.0;
        } else if pr >= quarter {
            score += 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // next item fits: residual is shared, mild reward scaled by fit tightness
            let tight = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large raw residual already;
    // add a mild opening cost so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // early in stream, opening bins is cheaper; late in stream, consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Prefer bins below mean residual (smaller residuals = tighter packing)
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Slight preference when many bins are open: consolidate rather than spread
    if open_bins_count > 4 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Post-residual that cannot fit the smallest plausible item (<= 100) is dead space;
    // moderate gaps (>= 10) are reusable, so scale penalty down there.
    if post_residual >= 10 {
        score += 0.15 * (post_residual as f64).sqrt() * 2.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
    }
    // If next item would be stranded by this placement, penalize.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than average (best-fit style sharpening).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of open bins that could still be used.
        score = 55.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 40 {
            score -= 20.0; // big next item: fresh bin is more attractive
        }
    }

    // Slight late-stream tightening: fewer chances remain, prefer tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for leftover space, amplified for small residuals (dead space)
    if post_residual > 0 {
        score += (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fill bin
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item nests in the remainder
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream: prefer tighter packing, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        // allow new bin early when lookahead suggests a large next item
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Waste that the next item cannot use.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 3.0 * pressure;

    // Progress-based horizon: late in stream, avoid leaving fragmented residuals.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * (post_residual as f64) * 0.5;

    // Prefer bins whose residual deviates below the mean (more filled already).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild bonus for using bins with larger residual when item is large (avoid opening bins for big items).
    if item_size > bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_n = post / cap;

    // Base: penalize wasted space, with non-linear (quadratic) growth in post_residual.
    let mut score = post + 40.0 * post_n * post_n;

    // Smooth interaction: late in the stream, tighter packing matters more,
    // so amplify the penalty on large post_residuals as progress -> 1.
    score += 60.0 * progress * post_n * post_n * post_n;

    // Reward tight fits: smooth bonus for small post_residual, stronger early-to-mid stream.
    let tightness = (-post_n * 4.0).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Dead-space penalty when residual becomes too small to fit typical future items.
    let dead = if post_residual > 0 && post_residual < item_size.max(next_item_size) { 1.0 } else { 0.0 };
    score += 18.0 * dead * (0.3 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / post;
        score -= 20.0 * (1.0 - fit_ratio) * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.02 * (open_bins_count as f64) * (mean_residual - post).abs() * 0.01;

    // New-bin candidate: penalize opening a new bin, more so when good fits exist.
    if bin_residual == bin_capacity {
        score += 45.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Reward tight fits: leftover in lowest eighth is nearly perfect.
    if post <= eighth {
        score -= 30.0;
    } else if post <= quarter {
        score -= 12.0;
    } else if post <= 2 * quarter {
        score += 5.0;
    } else {
        score += 18.0; // big dead space penalty
    }

    // Exact-fit harmonic bonus (post_residual divisible by common item classes)
    if post == 0 {
        score -= 50.0;
    } else if post % 10 == 0 && post <= 40 {
        score -= 8.0; // leftover likely reusable by future small items
    }

    // Lookahead coupling: penalize if the next item cannot use this leftover.
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits here's leftover — reward proportionally
            let slack = (post - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            if next_item_size == post {
                score -= 25.0; // perfect chain
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // open bins have poor fits. Penalize slightly; tight fits above will beat it.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
        return score;
    }

    // Prefer filling bins that are already well-loaded (residual close to item).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Mild stream-progress adaptation: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // Tie-break toward bins with low mean residual deviation (harmonized bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tightness reward: reward small-but-usable post residuals.
    if post_residual >= dead_threshold {
        score -= (bin_capacity - post_residual) as f64 * 0.25;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap < dead_threshold {
                score += chain_gap as f64 * 4.0; // chain would create dead space
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this gap: gap likely becomes dead
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly by rewarding existing bins).
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New-bin candidate: penalize proportionally to how many bins are already open.
        score += open_bins_count as f64 * 3.0;
        // Opening a new bin is attractive only when existing residuals are large/fragmented.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more willing to open bins (future flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item nests perfectly: big reward, stronger if exact.
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += 18.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a great 2-step chain
    // (item + next item fill it well); otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let chain_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if next_item_size > 0 && chain_fill > 0.9 {
            score -= 40.0 * chain_fill;
        } else {
            score += 30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: avoid wasting the only fitting bin on a poor fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    } else if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer filling bins with large residuals when many bins are open.
    let open_f = open_bins_count as f64;
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * open_f * residual_gap / bin_capacity as f64;

    // Time horizon: early in stream, encourage opening fresh bins for large items;
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or for big items, penalized late.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = 15.0 + 40.0 * progress - 20.0 * size_frac;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 6.0; // new bin can host next item too
        }
    } else if progress > 0.7 {
        score -= 6.0 * progress; // pack tighter near the end
    }

    // Slight bias toward bins that remain versatile after placement.
    score += 0.05 * (post_residual as f64 % 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let r_norm = r / cap;

