    let mut score = r + 12.0 * r_norm * r_norm - 8.0 * r_norm * r_norm * r_norm;

    // Smooth stream-progress coupling: later in the stream, tighten fits more aggressively
    let tighten = 10.0 * progress;
    score += tighten * r_norm * (1.0 - r_norm) * 4.0;

    // Reward near-perfect fits (small post residual) with a smooth bonus
    let fit_quality = 1.0 - (r_norm * 2.0 - 1.0).powi(2);
    score -= 14.0 * fit_quality * (0.5 + progress);

