    }

    // Last-chance bin bonus: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= 18.0 * (1.0 - r_norm);
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance)
    score += 0.08 * (r - mean_residual).abs();

    // Slight openness penalty as bins accumulate
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: mod-10 buckets. Residuals in
    // low classes (0-9) are "dead space" only if no future item can use them.
    let pr = post_residual;
    let class = pr % 10;
    // Class 0 (perfect multiple of 10) is highly reusable -> reward.
    if class == 0 {
        score -= 12.0;
    } else if class <= 3 {
        score += 4.0; // small awkward sliver, hard to fill
    } else if class >= 7 {
        score += 1.5; // large-ish but non-aligned
    }

    // Integer-division threshold: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: strong reward, scaled by how well it would fit
            let lookahead_post = pr - next_item_size;
            score -= 8.0 + (lookahead_post % 10 == 0) as i32 as f64 * 6.0;
        } else {
            // lookahead would need another bin; penalize leaving a gap
            // that is smaller than next item but larger than typical smalls
            if pr >= 10 && pr < next_item_size {
                score += 3.0;
            }
        }
    } else {
        // last item: just minimize post_residual, reward perfect closure
        if pr == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only prefer it when no open bin offers a good (class-0) fit.
    if bin_residual == bin_capacity {
        // neutral-ish base; let open bins with tight fits win
        score += 20.0;
        // early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.15 {
            score -= 10.0;
        }
        // if the item exactly fills the new bin, it's perfect
        if pr == 0 {
            score -= 60.0;
        }
    }

    // Mean-residual coupling: when open bins are generally full (low mean
    // residual), opening new bins is more acceptable; when mean residual is
    // high, discourage new bins further and encourage consolidating.
    if mean_residual > (bin_capacity as f64 * 0.5) {
        if bin_residual == bin_capacity {
            score += 10.0;
        }
    } else {
        // bins are mostly full; reward filling any existing bin tightly
        if pr <= 10 {
            score -= 5.0;
        }
    }

    // Modulo coupling between item and post_residual (harmonic alignment):
    // item_size % 10 == 0 items like to leave aligned residuals.
    if item_size % 10 == 0 && pr % 10 == 0 {
        score -= 4.0;
    }

    // Penalize huge dead space relative to smallest plausible item (1..100 range)
    if pr > 0 && pr < 10 {
        score += 6.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 120.0;
    }

    // Penalize leaving a gap that cannot host the lookahead item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
