    // 2-step lookahead: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        score -= 120.0 - (chain_waste as f64).min(80.0);
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize leaving dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Relative fit against mean residual: prefer bins whose residual is near item_size.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    // Penalize bins that are far below mean residual (badly fragmented) unless it's a tight fit.
    if (bin_residual as f64) < mean_residual - 5.0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so late in the stream with many open bins.
        score += 50.0 + 0.1 * (open_bins_count as f64);
        // But if next item is large and this item leaves a big residual elsewhere, new bin is safer.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
