    }

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, allow new bins when fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize if many open bins.
        score += 12.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        if post_residual == 0 && item_size == bin_capacity {
            score -= 100.0; // perfect fill of a fresh bin
