    // Reward bins that become exactly full.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mild penalty when many bins compete (prefer concentrating load).
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

