pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = bin_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Dead-space classes.
    else if post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual >= 30 {
        score -= 40.0;
    }

    // Tight-fit reward (non-linear).
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / ir;
        score -= 60.0 * fit_ratio * fit_ratio;
    }

    // Harmonic class discount.
    let class = post_residual / 10;
    score -= (class as f64) * 8.0;

    // Lookahead: next item nesting in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap);
            if slack < 10.0 && slack > 0.0 {
                score += 15.0;
            }
        } else {
            score += 18.0 * (1.0 - pr / cap);
        }
        let m = next_item_size % 10;
        if m == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many options but wasteful residual.
    if fitting_bins_count > 1 && post_residual >= 50 {
        score += 25.0;
    }

    // Mean residual coupling: prefer tighter-than-average bins.
    score += 0.3 * (pr - mean_residual).abs() - 0.3 * (mean_residual - pr);

    // Stream progression: allow more slack later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: open only for a great 2-step chain or no alternative.
    if bin_residual == bin_capacity {
        let chain_fill = (item_size + next_item_size) as f64 / cap;
        if next_item_size > 0 && chain_fill > 0.9 {
            score -= 40.0 * chain_fill;
        } else {
            score += 120.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        } else if fitting_bins_count == 1 {
            if bin_residual as i64 - item_size as i64 >= 50 {
                score -= 100.0;
            }
        }
        // New: also open a fresh bin when the best existing fit would leave
        // an awkward residual the next item cannot use, but the fresh bin
        // would host a tight 3-item chain.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let chain2 = (item_size + next_item_size) as f64 / cap;
            if chain2 > 0.95 {
                score -= 60.0 * chain2;
            }
        }
    }

    // New: penalize residuals that cannot host the next item at all,
    // scaled by how much space is wasted.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0 * (1.0 - pr / cap);
    }

    score
}

