pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible item (<= ~10% of capacity) are pure waste. Penalize
    // them hard, super-linearly.
    let dead_threshold = bin_capacity as f64 * 0.10;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Bonus for a perfect (or near-perfect) fill.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward
    // heavily; if next item cannot fit, mildly penalize leaving a mid gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            // next item fits: residual shrinks further, good
            score -= 5.0;
        }
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // But if this bin is the last chance, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin that fits: strongly prefer using it.
        score -= 25.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping larger residual bins available for bigger future items.
    score += (mean_residual - bin_residual as f64).abs() * 0.3
        - (bin_residual as f64 - mean_residual) * 0.2;

    // Slight time pressure: late in the stream, avoid leaving many tiny gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of next item into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // two-item exact fill: excellent
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-slack / 25.0).exp(); // decaying reward for near fits
        } else {
            // next item cannot fit here; penalize leftover dead space
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: bins with below-average residual are
    // "tight" bins; filling them is efficient, leaving them is wasteful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0).min(3.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating small unusable fragments (< 10, or below typical min size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate (empty bin): only attractive when current item leaves
    // a large, awkward residual in existing bins or no good fit exists.
