        // neutral base; slight bias toward using existing bins early on
        score += 5.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can host a 2-step chain
        }
    }

    score
}

