pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit), with slight convexity
    // to punish near-zero dead space more than moderate leftovers.
    let pr = post_residual as f64;
    score = pr * 0.9 + (pr * pr) / (bin_capacity as f64) * 0.6;

    // Lookahead: strongly reward if the next item fits into the post-residual,
    // with extra reward for a near-exact follow-up fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 - gap * 0.35;
        // Chain potential: next item leaves room for a third small item
        if gap >= 10 {
            score += gap * 0.15;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving large unusable gaps
        score += pr * 0.25;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin tendency indirectly by rewarding dense bins).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0 * (1.0 - t);
    }

    // Global residual context: if mean residual is high, packing here reduces fragmentation.
    if mean_residual > pr + 20.0 {
        score -= 4.0;
    } else if pr > mean_residual + 25.0 {
        // This bin is much emptier than average; keep it for future large items.
        score += 6.0 * (0.5 + t);
    }

    // New-bin candidate handling: an empty bin scores high (residual == capacity)
    // by default; only allow opening a new bin late in the stream or when the
    // current item is large and fits nowhere well.
    if bin_residual == bin_capacity {
        let base = 95.0;
        let large_item = item_size >= 60 && fitting_bins_count == 0;
        let late = t > 0.85;
        score = if large_item || (late && next_item_size >= 40) { 55.0 } else { base + item_size as f64 * 0.3 };
    }

    // Guard against pathological negative scores dominating everything.
    if score < 0.0 { score = 0.0; }
    score
