pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Stream progress coupling: later in the stream, penalize large residuals more
    score += 12.0 * progress * x * x * cap;

    // Dead-space penalty: residual too small to likely fit future items (items >= 1)
    let dead = 1.0 - (pr / 100.0).min(1.0);
    score += 25.0 * dead * dead * (0.5 + 0.5 * progress);

