    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidation relative to mean residual
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only when
    // open bins have poor fits; smooth polynomial in progress
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress * (1.0 - progress);
    }

    // Slight penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

