        if r <= 15 {
            score -= 15.0; // tiny leftover is effectively dead space -> reward using it up
        }
        score -= bonus;

        // Lookahead coupling: if next item fits into post_residual, reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0 + 0.25 * (next_item_size as f64);
        } else if next_item_size > 0 {
            // Next item won't fit here; penalize more if post_residual is awkwardly sized.
            score += 6.0 * ((cap - pr) / cap);
        }

        // Last-chance bin: strongly favor using the only fitting bin.
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 40.0;
        }

        // New-bin candidate: opening a bin wastes capacity; make it costly unless
        // current bin fit is poor (large post_residual) or few bins open.
        if bin_residual == bin_capacity {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            // Prefer new bin early (cheap to spread) or when item leaves big hole elsewhere.
            score += 55.0 - 30.0 * progress;
            if next_item_size > 0 && next_item_size <= bin_residual {
                score -= 10.0;
            }
            // If existing bins would leave big dead space, new bin is attractive.
            if pr > 0.5 * cap {
                score -= 45.0;
            }
        }

        // Mean-residual coupling: prefer bins below mean residual (tighter bins).
        score += (mean_residual - pr) * 0.15;

        // Many open bins: prefer consolidating into existing bins.
        score += open_bins_count as f64 * 0.4 * (pr / cap);
    }

    score
