pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    }

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure on number of open bins: discourage opening new bins when many exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 5.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits into the post residual,
    // this is a great pairing; reward it proportionally to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 80.0 - pair_waste * 0.8;
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize leftover
        // dead space that is small and unusable.
        let unusable = post_residual as f64;
        if unusable < next_item_size as f64 {
            score += (next_item_size as f64 - unusable) * 0.5;
        }
    }

    // Perfect 2-item fill: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Compare residual against the mean residual of open bins:
    // placing into a bin with below-mean residual keeps big gaps
    // available for larger future items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 40.0;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly penalize so we only open new bins
    // when open bins are genuinely poor fits; but keep it competitive
    // when the current bin would leave a big unusable gap.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If item is large relative to capacity, opening a fresh bin
        // for it is actually fine (keeps small residual bins flexible).
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 70.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins
    // (keeps flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 30.0;
    } else {
        score -= progress * 20.0;
    }

    // Discourage leaving residuals in the awkward 20-40 range
    // (hard to fill for typical item sizes).
    if post_residual >= 20 && post_residual <= 40 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity (good fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64);

    // Lookahead (k=2): if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
