    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let penalty = 30.0 + 45.0 * (1.0 - pressure) + 20.0 * progress
            + 15.0 * (open_bins_count as f64).ln().max(0.0);
        // If item is large and fits poorly nowhere, new bin is more acceptable.
        let size_relief = (item_size as f64 / bin_capacity as f64) * 25.0;
        score += penalty - size_relief;
    } else {
        // Reward reusing existing bins, scaled by how full they already are.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Global state coupling: prefer bins whose residual is close to the mean residual
    // (keeps residual distribution balanced, avoids stranding extreme bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late-stream consolidation: as stream progresses, avoid leaving many tiny residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
