    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late, penalize them quadratically.
    let w = 0.5 + 2.5 * progress * progress;
    score += w * norm_post * norm_post * cap * 0.5;

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 {
        let dead = ((20.0 - post_residual as f64) / 20.0).max(0.0);
        score += 6.0 * dead * dead * (0.3 + 0.7 * progress);
    }

    // Reward tight fits (small post_residual relative to item).
    score -= 8.0 * norm_item * (1.0 - norm_post);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 4.0 * norm_next;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 {
        score += 2.0 * norm_next * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: prefer it when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let gap = (post_residual as f64 - norm_post * cap).max(0.0);
        score += 3.0 * crowd + 2.0 * (1.0 - norm_item) - 1.5 * (1.0 - progress);
        let _ = gap;
    }

    // Diverge from mean residual: smooth coupling term.
    score += 0.05 * (post_residual as f64 - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 8 classes
    let cap = bin_capacity as f64;
    let class = (post_residual * 8) / bin_capacity; // integer division: 0..=7
    let class_bonus: f64 = match class {
        0 => 0.0,          // perfect fit class
        1 => 6.0,          // tiny dead space (usable only by very small items)
        2 => 2.0,
        3 => 4.0,
        4 => 1.0,          // half-capacity residual is highly reusable
        5 => 3.0,
        6 => 2.5,
        _ => 5.0,          // large residual, generally fine
    };
    score += class_bonus;

    // Exact-fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residuals that exactly admit the lookahead item (harmonic pairing)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            // residual covers next item: mild reward scaled by slack
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual: penalize small leftovers
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 5.0; // dead space just below next item
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / cap;
        // penalize new bins generally, less so when open bins are crowded
        score += 12.0 - 10.0 * fragmentation - 6.0 * progress;
        // if no open bin fits well (this call is the empty bin and few fit), ease penalty
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins when many bins are open
    score -= 3.0 * (1.0 - bin_residual as f64 / cap) * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    // Any gap < 10 (min plausible item) is dead space; gaps that can't hold next item are risky.
    if post_residual < 10 {
        score += 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect fit for the lookahead item: strongly reward.
        score -= 25.0;
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless this fit is very tight
    // or open-bin pressure is high.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 25.0 * tightness;
        score += 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit coupling) beyond raw post_residual.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Open-bin pressure: many open bins -> favor filling existing ones (penalize new bins implicitly,
    // reward using bins whose residual is below mean, i.e., tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * (open_bins_count as f64 / (total_items.max(1) as f64)).min(2.0);
    }

    // Late in stream: be more conservative, prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0; // next item exactly fills this bin afterwards
        } else if diff <= 10 {
            score -= 150.0;
        } else if diff <= 25 {
            score -= 40.0;
        } else {
            // penalize leaving large unusable gaps relative to next item
            score += (diff as f64 - 25.0) * 0.8;
        }
    } else {
        // Last item: just prefer tightest fit
        score += 0.0;
    }

    // Penalize deviating far from mean residual (favor bins with typical fill level,
    // avoid fragmenting outliers).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New empty bin candidate: penalize unless few fitting bins exist or lookahead
    // suggests a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild preference for filling bins as stream progresses (close out bins early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early on, be picky (penalize mediocre fits); late, fill greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Fragmentation pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = mean_residual / (bin_capacity as f64) * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are very full
        // (low mean residual) or post_residual would be very poor elsewhere.
        score += 10.0 + pressure * 8.0;
    } else {
        score -= pressure * 2.0;
    }

    // Slight preference for fuller bins when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Non-linear reward for tight fits: quadratic coupling of fill ratio
    let fill_ratio = 1.0 - post / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Smooth stream-progress coupling: later in stream, tolerate less dead space
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_weight * post * 0.35;

    // Penalize bins whose residual deviates from mean (keep residual diversity balanced)
    let dev = post - mean_residual;
    score += 0.08 * dev * dev / cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // but allow it when post residual would be large and reusable for next item
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0 - 15.0 * progress;
        // If next item fits perfectly into the fresh post residual, favor new bin
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            let next_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
            score -= 10.0 * next_fit;
        }
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Dead space for the lookahead item: penalize unusable residue
        let waste = (next_item_size as f64 - post) / cap;
        score += 8.0 * waste * waste;
    }

    // Many open bins: prefer consolidating into existing bins
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: post_residual mod 10 defines
    // "resonance" classes. Leftovers that are exact multiples of 10 are
    // more reusable by future items, so reward (subtract) them.
    let class = post_residual % 10;
    let harmonic_reward = match class {
        0 => 12.0,
        5 => 6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_reward;

    // Integer-division threshold: tiny dead space (post_residual < 10)
    // is nearly unusable given min item size ~1..100 unknown; penalize
    // strongly only if it falls below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post_residual, this is a harmonic chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            if next_left % 10 == 0 {
                score -= 10.0;
            }
            score += (next_left as f64) * 0.15;
        } else {
            // next item cannot use this bin's leftover; mildly penalize
            // wasting a large residual on a small item.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Fraction of capacity filled by this item: reward high fill ratio.
    let fill = item_size as f64 / cap;
    score -= fill * 20.0;

    // Last-chance bin: if this is the only fitting bin, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate: make empty bin attractive only when residuals
    // across open bins are collectively tight (mean_residual small) or
    // when this bin's post-residual would be an awkward class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < 15.0;
        if tight {
            score -= 5.0; // open fresh bin when everything is full-ish
        } else {
            score += 10.0 + 10.0 * progress; // prefer reusing open bins early
        }
    }

    // Penalize creating residuals far from mean (fragmentation spread).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 12.0; // near-perfect fit still attractive if gap is potentially usable
    }

    // Reward filling a bin deeply relative to capacity.
    score -= 0.35 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: many open bins -> prefer reuse of existing bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 9.0 {
                score -= 20.0;
            } else {
                score += 0.15 * slack;
            }
        } else {
            // next item cannot fit here; slightly penalize leaving this residual
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // a fragmented bin; prefer consolidating space.
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current bin would leave a large residual (poor fit) and bin pressure is high.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = 55.0 + 3.0 * open_bins_count as f64;
        // if item is large, fresh bin is fine
        if item_size >= 50 {
            score -= 25.0;
        }
        // if no open bin fits (this call is the only option), make it attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in the stream, avoid spawning bins that will strand space
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial reward for leaving room for the next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize relative to how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 20.0 * miss / bin_capacity as f64;
    }

    // Penalize dead space (small unusable residuals).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with below-average residual (tighter packing) when post_residual is small.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a brand-new bin when open bins could fit and residuals are healthy.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_bonus = if open_bins_count > 0 && fitting_bins_count > 0 { 60.0 } else { 0.0 };
        score += open_bonus + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in stream, be more conservative (prefer tight fits);
    // later, allow new bins more freely since waste matters less per-item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let urgency = (1.0 - progress).powf(1.5);

    // Penalize large post-residual more strongly as stream progresses (dead space compounds).
    score += (post_residual as f64) * 0.15 * (1.0 - progress);

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual <= 10 {
        score -= 40.0 * (11.0 - post_residual as f64);
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 * urgency;
    }

    // Lookahead coupling: if next item could fit into this bin's post-residual,
    // reward placing here (keeps future options open).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (post_residual as f64 - next_item_size as f64 + 1.0).sqrt();
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Penalize leaving a residual that's too small for the next item (dead space).
        score += 15.0 * urgency;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty
    // so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 70.0 * urgency;
        // But if the item is large relative to capacity and mean residual is small,
        // opening fresh is attractive.
        let density = item_size as f64 / bin_capacity as f64;
        score -= 90.0 * density * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        // Late in the stream, new bins are cheaper.
        score -= 50.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > bin_capacity as f64 * 0.3 {
        score -= 20.0;
    }

    // Mild penalty for wasting a very large bin residual on a small item.
    if item_size < 20 && bin_residual > 80 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * prog2 + prog3);
    score += 20.0 * coupling;

    // Penalize large dead space more than linearly (quadratic term)
    score += 15.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits, stronger late in the stream
    score -= 25.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead: reward bins whose post_residual matches the next item smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_quality = 1.0 - ((pr - norm_next * cap) / cap).abs();
        score -= 12.0 * match_quality * match_quality * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 8.0 * progress;
    }

    // Last-chance bonus: only fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - norm_pr) * (1.0 - 0.5 * progress);
    }

    // Penalize deviation from mean residual (prefer balanced bins), smoothed
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for proliferation of open bins early on
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: prefer it only when post_residual is perfect or stream is early
