pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny gap = pure dead space
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        } else {
            score -= 10.0; // large residual still reusable
        }
    } else {
        score -= 40.0; // perfect fit, strongly reward
    }

    // Open-bins pressure: discourage spreading across many bins.
