    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space
    // or the next item fits better in a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + progress * 10.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 20.0; // fresh bin reserves room for the lookahead item
        }
        if post_residual > 0 && post_residual <= 20 {
            score += 15.0; // current placement would create dead space
        }
    }

    // Lookahead: penalize if the leftover cannot host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Mild tie-break toward bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial reward when next item still fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
