    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild penalty for opening a new bin when plenty of bins fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 + 5.0 * (fitting_bins_count as f64).ln().max(0.0);
