pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize small dead space that no future item (min size 1) can use well
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 40.0;
    }

    // Reward filling bins that are already quite full (low residual)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Lookahead: if the next item fits the post-residual exactly, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 20.0;
        } else {
            // Next item won't fit here; slight penalty if post-residual becomes dead space
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 250.0;
        // Cheaper to open a new bin early in the stream (more items remain to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 60.0;
        // If many open bins already, consolidating is better than adding more
        score += open_bins_count as f64 * 5.0;
        // If existing bins fit poorly (large item relative to residuals), new bin is more attractive
        let poor_fit = if mean_residual > 0.0 { (item_size as f64 / mean_residual).min(2.0) } else { 2.0 };
        score -= poor_fit * 40.0;
        // Big items with lookahead of another big item: fresh bin helps
        if next_item_size >= item_size && item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward when mean residual is high (bins are loose, easy to place)
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Global pressure: when many bins are open relative to items seen, avoid opening more
    let bins_per_item = if step_index > 0 { open_bins_count as f64 / (step_index as f64 + 1.0) } else { 0.0 };
    score += bins_per_item * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

