    // Early in the stream, keep bins flexible (large residuals acceptable);
    // late in the stream, strongly prefer bins that end up nearly full.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Non-linear reward for tight fits: cubic term in normalized post residual.
    let norm_pr = pr / cap;
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

