    // A bin whose post residual is far below the mean is efficiently used.
    score -= 0.5 * (mean_residual - pr) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild preference among multiple candidates: favor fuller bins.
        score -= 1.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: if the next item would fit in the post residual,
    // reward this placement (keeps chains of items in one bin).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Penalize leaving a dead-space gap too small for the next item.
        score += 1.5 * (pr / cap) * (pr / cap);
    }

    // New-bin candidate handling: an empty bin has huge post residual,
    // so the polynomial terms already penalize it; add a mild extra
    // penalty early on and a stronger one when open bins exist and fit well.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets
    // using integer division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual <= 10 -> nearly perfect fit, strong reward.
    if post_residual <= 10 {
