    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the follow-up fit
            score -= 10.0 * (nxt / (post + 1.0));
            if post_residual - next_item_size <= 5 {
                score -= 15.0; // chain of tight fits
            }
        } else {
            // next item does NOT fit here: penalize more if post_residual is
            // in the "teasing" band where it nearly fits (harmonic near-miss)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 12.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline that
    // loses only when an open bin offers a genuinely tight fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * mean_residual.abs();
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: prefer fresh capacity
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Progress-based tilt: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual <= 25.0) as i32 as f64;

    // Small tie-breaker on exact-fill modulo classes (residual divisible by 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
