    // allow opening new bins when fits are mediocre.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 3.0 * (1.0 - 0.5 * progress);
    score += pressure;

    // New-bin candidate calibration: empty bin gets post_residual == bin_capacity.
    // Make it attractive only when the item is large relative to mean residual
    // (i.e., existing bins would be badly fragmented).
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.75;
