        score -= 1.0;
    } else {
        score -= 3.0;            // large residual keeps bin flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item leaves a well-classed remainder
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 5.0;
            }
            score -= (next_item_size.min(post_residual)) as f64 * 0.05;
        } else {
            // next item won't fit here; mildly penalize tight bins
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (bin_residual - item_size) as f64;
        // prefer new bin if all existing fits would leave very small residuals
        let threshold = 25.0 + 20.0 * (1.0 - progress);
        if poor_fit < threshold && fitting_bins_count > 0 {
