        let nxt = next_item_size as f64;
        if nxt > 0.0 && nxt <= post {
            score -= 10.0;
        }
        return score;
    }

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item / res.max(1.0); // fraction of residual consumed
    score -= tightness * 40.0;

    // Penalize leaving awkward dead space: post_residual in a "dead zone"
    // (too small for the smallest items, i.e. < 10) is fine; mid-size waste is bad.
    if post > 0.0 && post < 10.0 {
        score -= 15.0; // perfect sealing of the bin
    } else if post >= 10.0 && post < 25.0 {
        score += 8.0; // awkward gap likely wasted
    }

    // Lookahead coupling: if the next item fits exactly into the resulting gap,
    // reward heavily; if next item nearly fits but misses, penalize.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        if nxt <= post {
            score -= (1.0 - post / nxt.max(1.0)) * 12.0 + 5.0; // next item fits
        } else if nxt <= post + 8.0 {
            score += 10.0; // painful near-miss
        }
    }

