    // on a poor fit, but avoid rejecting entirely (no alternative).
    if fitting_bins_count == 1 {
        score -= 5.0;
        if post > 30.0 {
            score += 12.0; // dumping a big item into the last bin wastes space
        }
    }

    // Global state: prefer bins whose residual deviates from the mean in a
    // useful way — filling below-mean-residual bins first keeps large gaps open.
    let dev = res - mean_residual;
    score += dev * 0.15;

    // Time horizon: late in the stream, consolidate aggressively.
    score -= t * 6.0 * (1.0 - tightness);

    // Mild preference for bins with less residual overall (best-fit bias).
    score += res * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

