    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize bins with residual far from mean (fragmentation) smoothly.
    score += ((mean_residual - bin_residual as f64) / cap).abs() * 5.0 * (0.5 + progress);

    // Lookahead coupling: if next item could fit into the post residual, reward it smoothly.
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as f64;
        let closeness = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= next_fits * closeness * 12.0 * (1.0 - progress);
    }

    // Mild penalty for opening a new bin when many bins are already open.
