pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "usable" is the post residual
    // for typical item sizes? Items are 1..100, so classify post_residual by
    // its residue modulo 10 and by which capacity-fraction band it lands in.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // capacity fraction of remaining space

    // Fraction-band reward: tight fits (small fraction) are excellent.
    if frac <= 0.05 {
        score -= 60.0; // near-perfect fit
    } else if frac <= 0.15 {
        score -= 35.0;
    } else if frac <= 0.30 {
        score -= 15.0;
    } else if frac > 0.70 {
        // Large residual: only good if this is a fresh bin
        if bin_residual == bin_capacity {
            score -= 20.0;
        } else {
            score += 10.0; // wasteful mostly-empty bin
        }
    }

    // Modulo-10 harmonic class: residuals divisible into common item-size
    // classes (10,20,...) are more likely to be filled by later items.
    let r10 = post_residual % 10;
    if post_residual > 0 {
        if r10 == 0 {
            score -= 12.0; // perfectly aligned with decade classes
        } else if r10 >= 7 {
            score += 6.0; // awkward sliver like 7,8,9 extra
        }
    }

    // Dead-space penalty: residual below the minimum plausible item size (1),
    // but penalize very small unusable gaps strongly relative to item size.
    if post_residual < item_size.min(next_item_size.max(1)) && post_residual > 0 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect packing
    }

    // Lookahead coupling: does next item fit in post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Harmonic bonus if next item's size class matches residual class
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate: prefer existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + open_bins_count as f64 * 2.0;
    }

    // Spread-awareness: bins far from the mean residual are less attractive
    // unless they are very tight.
    let dev = (post_f - mean_residual).abs();
    score += dev * 0.05;

    score
