            // Next item still fits here: good, but reward tighter coupling.
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 - slack * 0.4;
        } else {
            // Next item cannot use this residual: penalize proportional dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    } else {
