    // Favor bins whose residual is above mean (they can absorb the item while
    // tighter bins stay available for other items), but not too far above.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // ---- Last-chance bonus: only fitting bin; avoid opening a new bin ----
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // ---- Tightness reward: small post-residual is good, but avoid slivers ----
    if post_residual > 0 && post_residual < 5 {
        // Tiny slivers are nearly unusable dead space.
        score += 8.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    // ---- Stream progression: late in stream, prefer exact consumption ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // ---- Many open bins: prefer consolidating into fuller bins ----
    if open_bins_count > 4 {
        score += (bin_residual as f64) * 0.05;
    }

    score
}

