        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Penalize creating dead space that cannot hold typical small items.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
