    score += 30.0 * late_warp * norm_post * norm_post;

    // Reward near-perfect fits with a smooth bump centered at post_residual = 0.
    score -= 25.0 * (-(norm_post * norm_post) / 0.02).exp();

    // Interaction between item size and leftover: large items into roomy bins
    // are slightly favored (avoid fragmenting small bins with big items).
