pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) - norm_post * (0.5 + 0.8 * progress);
    let mut score = post * (1.0 + poly.abs());

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (cap - post) * (0.1 + 0.5 * progress * progress) / cap;

    // Penalize dead space: residual too small to be useful later
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 5.0 * (post - next) / cap;
        } else {
            score += 3.0 * (next - post) / cap;
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * (post - mean_residual).abs() / cap;

    // Dampen bin proliferation early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: group post_residual into capacity-fraction bands.
    let frac = post_residual as f64 / cap; // (0,1)
    // Integer-division thresholds on post_residual: dead-space classes
    let class = post_residual / (bin_capacity / 8); // 0..8 harmonic class
    score += match class {
        0 => 6.0,      // near-perfect fill, reward heavily
        1 => 2.0,      // small sliver, still useful
        2 => 0.0,
        3 => -1.0,
        4 => -2.0,     // half-full leftover, versatile
        5 => -1.0,
        6 => 1.5,
        _ => 4.0,      // mostly empty, wasteful placement
    };

    // Modulo coupling: leftover that matches common item-size residues is reusable.
    let m = post_residual % 10;
    if m == 0 { score -= 3.0; }              // multiple of 10 aligns with typical sizes
    else if m >= 8 { score += 2.0; }         // awkward remainder

    // Lookahead: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 + 4.0 * (1.0 - slack / cap); // tight two-item chain is great
        } else {
            score += 1.0; // next item won't fit here
        }
        // modulo harmony between leftover and next item size
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New empty bin candidate: usually worse than reusing a fitting bin,
    // but attractive for huge items or when fit is terrible everywhere.
    if bin_residual == bin_capacity {
        let base = 8.0 + 0.15 * open_bins_count as f64;
        let relief = if post_residual as f64 / cap < 0.25 { 14.0 } else { 0.0 };
        score += base - relief;
    }

