    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 2.0;

    // Slight preference for fewer open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0;

