    // Open-bin pressure: many open bins with large mean residual -> prefer new bin
    // to avoid fragmentation; few open bins -> reuse
    let pressure = mean_residual / cap - 0.5;
    score += 15.0 * pressure * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: an empty bin has post_residual == capacity;
    // penalize opening a new bin unless existing placements would leave large waste
    if bin_residual == bin_capacity {
