    // Small dead-space cliff: residuals below smallest plausible item (1..100 unknown,
    // but items >= 10 typical) become dead weight
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual < 25 {
        score += 6.0;
    }

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
