    }

    // Mean residual coupling: bins with residual far below mean are scarce-resource;
    // placing into them wastes their smallness. Prefer bins near/above mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
        // if no open bin fits, opening is nearly forced
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize dead space proportionally
            score += 15.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).min(1.0);
        }
        // small residual after hypothetical next placement
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 > 0 {
            score += post2 as f64 * 0.3;
        }
    }

    // Penalize large dead space relative to mean residual
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are truly bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // more acceptable late in stream or when few bins fit
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Tight fits are good
    score -= 10.0 * (item_size as f64 / bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward closing a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead (k=2): reward leaving room the next item can use,
    // penalize leaving a gap just larger than the next item's need.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
        } else {
            let waste = (next_item_size as f64 - post_residual as f64).min(60.0);
            score += 0.3 * waste;
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // If no open bin fits, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            // Penalize abandoning usable residual space; harsher early in the stream.
            score += 300.0 + 250.0 * (1.0 - progress);
        }
        // Reward opening a fresh bin when the next item is large and this
        // placement would leave the current bin too tight for it.
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 80.0;
        }
    }

    // Global coupling: mildly prefer bins whose residual is tighter than the
    // mean residual (best-fit tendency relative to global state).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Small penalty for very large dead space creation.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

