    // Reward tight fits: subtract when post_residual is small relative to mean residual
    let mean_norm = mean_residual / cap;
    score -= 0.5 * (mean_norm - pr_norm).max(0.0) * (1.0 - progress);

    // Lookahead: favor bins whose post residual can host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.4 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.25 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
