pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is more wasteful
    let class_size = 10u32;
    let post_class = post_residual / class_size;
    let post_frac = (post_residual % class_size) as f64 / class_size as f64;
    // Penalize classes where residual is too small for typical items (1..10 = dead)
    let dead_penalty = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    score += dead_penalty;

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic coupling: does next item fit into post_residual? Reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted space
        score += 0.1 * post_residual as f64;
    }

    // Modulo-based "harmonic" bonus: residuals divisible by common item sizes
    // (10,20,25,50) keep the bin usable for future harmonic classes
    let harmonic_bonus = if post_residual == 0 { 0.0 }
        else if post_residual % 50 == 0 { 12.0 }
        else if post_residual % 25 == 0 { 8.0 }
        else if post_residual % 20 == 0 { 6.0 }
        else if post_residual % 10 == 0 { 4.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // But if placing here would strand the current bin (post_residual tiny/dead),
        // opening fresh is better: reduce new-bin score
        let would_strand = post_residual > 0 && post_residual < 10;
        if would_strand {
            score -= 45.0;
        }
        // Early in stream, new bins are cheap; later, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins open already, discourage spreading
        score += 1.5 * open_bins_count as f64;
    }

    // Fractional capacity coupling: prefer bins whose fill ratio lands on "nice" fractions
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let frac_penalty = (fill * 4.0).round() / 4.0 - fill; // distance to quarter marks
    score += 5.0 * frac_penalty.abs();

    // Mean-residual anchoring: prefer bins close to mean residual (balance)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Slight preference for tighter fits overall
    score += 0.02 * post_residual as f64 * post_frac;

