pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are near-perfect fits and get rewarded.
    let residue_class = post_residual / 10; // 0..=10 harmonic decile
    let class_bonus: f64 = match residue_class {
        0 => 12.0, // perfect fill (post_residual < 10) — highly desirable
        1 => 8.0,
        2 => 5.0,
        3 => 2.0,
        4 => 0.0,
        5 => -1.5, // half-full leftovers are awkward
        6 => -2.0,
        7 => -2.5,
        8 => -3.0,
        9 => -3.5,
        _ => -5.0, // barely touched bin: wasteful placement
    };
    score -= class_bonus;

    // Modulo coupling: if next item can exactly reuse the post residual,
    // strongly reward (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap < 10 {
            score -= 6.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead-space creation,
        // scaled by how small the stranded residue is.
        score += (10 - residue_class.min(10)) as f64 * 0.6;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: an empty bin is a blank slate.
    // Prefer it only when no open bin offers a decent fit (large post_residual
    // relative to capacity) or when the item is large and fragmentation is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
