        score += 5.0;
        // But if open bins would leave huge ugly residue, encourage fresh bin.
        if post_residual_proxy_would_be_bad(item_size, bin_capacity) {
            score -= 10.0 + 4.0 * fragmentation + 10.0 * progress;
        }
    }

    // Mild global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= consolidation * 2.0;
    }

    score
}

