pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // Gaps below the minimum item size (1..~10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Also penalize gaps that can't fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; mild since new-bin candidate must remain viable.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline; only prefer a new bin
    // when this open bin would create severe dead space (handled above).
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
        // But if no open bin fits well, new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: slightly favor consolidation; late stream: keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match
        } else if post_residual >= next_item_size {
            let left_after_next = post_residual - next_item_size;
            // Penalize leftover that is small and unusable (< 10 typical min size)
            if left_after_next < 10 {
                score += 25.0;
            } else {
                score -= 10.0 * (left_after_next as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot fit here: leftover will be dead space
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 20.0;
            }
            score += 8.0;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: penalize so it's only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Slight pressure late in the stream to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
