pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction classes.
    // Classes: 0 (perfect fit), tiny (1..=10), small (11..=25), mid (26..=49), large (>=50).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits strongly (waste minimization, quadratic penalty on waste).
    score += (pr * pr) / cap;

    // Class bonuses via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 30.0; // near-perfect: dead space almost unusable anyway
    } else if post_residual <= 25 {
        score -= 10.0;
    } else if post_residual >= 50 {
        // Large leftover is only good if it can host the lookahead item.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0; // large unusable gap
        }
    }

    // Modulo-10 harmonic class: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more "usable" for typical discrete item sizes.
    let r = post_residual;
    if r % 10 == 0 { score -= 6.0; }
    if r % 25 == 0 { score -= 4.0; }
    if r >= 10 && r % next_item_size.max(1) == 0 && next_item_size > 0 {
        score -= 8.0; // exact harmonic match with lookahead
    }

    // Lookahead coupling: penalize leaving a gap that almost-but-not-quite fits next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap > 0 && gap <= 5 {
            score += 15.0; // agonizing near-miss dead space
        } else if gap <= 0 && gap >= -(next_item_size as i64) {
            // next item won't fit here regardless; slight penalty for wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-worse unless item is huge
    // relative to all residuals or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_gap = mean_residual;
        // Prefer new bin when item is large and mean residual is small (fragmentation risk).
        if item_size as f64 > 0.7 * cap && avg_gap < 0.5 * cap {
            score -= 20.0;
        } else if progress < 0.2 && open_bins_count < 3 {
            score -= 5.0; // early stream: cheap to spread out
        } else {
            score += 10.0; // default: prefer existing bins
        }
        // New empty bin wastes capacity proportional to item size.
        score += (bin_capacity - item_size) as f64 * 0.3;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..=100 range),
    // but weight it super-linearly as the gap shrinks.
    let dead_zone = 10.0; // gaps below ~10 units are nearly unusable
    if post > 0.0 && post < dead_zone {
        score += (dead_zone - post) * (dead_zone - post) * 2.0; // quadratic dead-space penalty
    }
    // General tightness reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 60.0;

    // Penalize large leftover space only mildly (it may still be usable),
    // but penalize medium leftover space that is awkward relative to mean residual.
    if post > dead_zone {
        score += post * 0.15;
        if post as f64 > mean_residual {
            score += (post - mean_residual) * 0.2;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another bin;
    // with few open bins, a new bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost + pressure term.
        score = cap * 0.5 + new_bin_pressure * 8.0;
        // If this bin is the last chance and the fit is decent, strongly discourage new bin.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
        // If lookahead item could pair with the post-residual of an existing bin,
        // opening a new bin is slightly less attractive.
        if next_item_size > 0 && (post_residual as f64 + next_item_size as f64) <= cap {
            score += 10.0;
        }
    } else {
        // Existing bin: reward being the last chance (avoid opening new bins).
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Lookahead synergy: if the next item exactly fills the post-residual, big reward.
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 80.0;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            // Next item cannot use this gap: mild penalty for stranded space.
            score += post.min(next_item_size as f64) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would fit; mild penalty proportional to waste.
            let waste_after_next = post_residual - next_item_size;
            score += 0.5 * waste_after_next as f64;
            // Small bonus if the next item still fits (chain of placements).
            score -= 20.0;
        } else {
            // Next item cannot use the leftover: dead space penalty.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins would create excessive dead space.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Late in the stream, opening new bins is less costly (fewer future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
    }

    // Tight-fit preference: smaller post_residual relative to bin capacity is better.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0;

