pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item nearly fills remaining space.
        if post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual can't hold next item: mild penalty proportional to wasted potential.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins that fit.
        score += 45.0 + 8.0 * fitting_bins_count as f64;
        // If no open bin fits, opening a new bin is necessary: reduce cost.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream, prefer packing into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Global state coupling: when mean residual is high, prefer bins below mean
    // (drain laggard bins), when low, prefer best fit anywhere.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev;
    }

    // Many open bins: encourage consolidation into fuller bins.
    if open_bins_count > 4 {
        score += 0.5 * (post_residual as f64 / bin_capacity as f64) * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: quadratic-ish preference for small post_residual
    let mut score = pr * (1.0 + 0.5 * pr_norm);

    // Smooth non-linear coupling with stream progress: late in the stream,
    // penalize large residuals more strongly (tighten packing toward the end).
    let progress_coupling = 4.0 * progress * (1.0 - progress); // peaks mid-stream
    score += pr_norm * pr_norm * cap * (0.5 + progress_coupling);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= (1.0 - pr_norm).powi(3) * 10.0 * item_norm;

    // Dead-space penalty: residuals too small for the smallest plausible next item
    let next = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    if next > 0.0 && pr < next {
        score += (next - pr) * (1.0 + progress);
    }
    // If next item fits exactly in the post-residual, reward smoothly
    if next > 0.0 && pr >= next {
        let fit_quality = 1.0 - ((pr - next) / cap);
        score -= 6.0 * fit_quality * fit_quality;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild diversity pressure: when many bins are open, favor bins below mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).sqrt().ln().max(0.0);

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr / 10; // decile class 0..10
    // Dead space penalty grows super-linearly for small unusable residuals (1..9)
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64;
    }
    // Perfect fit is heavily rewarded
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0; // chain of perfect fits
        } else if next_item_size <= pr {
            let new_pr = pr - next_item_size;
            // reward if next placement also lands in a good class
            if new_pr == 0 {
                score -= 40.0;
            } else if new_pr < 10 {
                score += 10.0 * (10 - new_pr) as f64;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize by leftover class
            score += 8.0 + class as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer tighter bins among many fitting candidates
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Mild pressure to reuse open bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);

    // Prefer bins whose residual deviates favorably from the mean
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when current residuals are nearly full
    if bin_residual == bin_capacity {
        let tight_open = if mean_residual < 15.0 { -20.0 } else { 30.0 };
        score += 10.0 + tight_open + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 0.0; // empty bin always fits next item exactly at start
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 20 {
