    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0));
    score += pressure * 3.0;

    // Mean-residual coupling: prefer bins tighter than the mean (good packing).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: only attractive when item is large and
    // existing residuals would leave big dead space.
    if bin_residual == bin_capacity {
