        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // If many open bins with small residuals, opening fresh is fine.
        if mean_residual < 25.0 && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    score
}

